import 'dart:convert';
import 'package:flutter/material.dart';import 'package:flutter_map/flutter_map.dart';import 'package:flutter_map_pmtiles/flutter_map_pmtiles.dart';import 'package:latlong2/latlong.dart';import 'package:shared_preferences/shared_preferences.dart';
import '../../models/offline_map_models.dart';import 'offline_map_storage.dart';
class OfflineAwareTileLayer extends StatefulWidget{const OfflineAwareTileLayer({super.key,required this.origin,required this.destination,this.onSourceChanged});final LatLng origin,destination;final ValueChanged<String>? onSourceChanged;@override State<OfflineAwareTileLayer> createState()=>_S();}
class _S extends State<OfflineAwareTileLayer>{Future<_ResolvedLayer>? future;@override void initState(){super.initState();future=_resolve();}@override void didUpdateWidget(covariant OfflineAwareTileLayer old){super.didUpdateWidget(old);if(old.origin!=widget.origin||old.destination!=widget.destination)future=_resolve();}
Future<_ResolvedLayer> _resolve()async{final prefs=await SharedPreferences.getInstance();final raw=prefs.getString('offline_map_manifest_cache_v1');if(raw!=null){try{final packs=(jsonDecode(raw) as List).whereType<Map>().map((x)=>OfflineMapPack.fromJson(Map<String,dynamic>.from(x))).toList();final resolution=await OfflineMapStorage().resolve(packs,widget.origin,widget.destination);if(resolution.source==MapSourceKind.offlineMap&&resolution.localRecord!=null){final provider=await PmTilesTileProvider.fromSource(resolution.localRecord!.filePath);return _ResolvedLayer(provider,'OFFLINE_MAP');}}catch(_){}}return const _ResolvedLayer(null,'ONLINE_OSM');}
@override Widget build(BuildContext context)=>FutureBuilder<_ResolvedLayer>(future:future,builder:(context,s){final r=s.data??const _ResolvedLayer(null,'ONLINE_OSM');WidgetsBinding.instance.addPostFrameCallback((_)=>widget.onSourceChanged?.call(r.source));if(r.provider!=null)return TileLayer(tileProvider:r.provider!);return TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.udrive.mobile');});}
class _ResolvedLayer{const _ResolvedLayer(this.provider,this.source);final PmTilesTileProvider? provider;final String source;}
